package com.eventhub.service;
import com.eventhub.dto.*; import com.eventhub.entity.*; import com.eventhub.repository.*; import com.eventhub.util.TicketSecurity; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*; import java.util.*;
@Service @RequiredArgsConstructor
public class RegistrationService{private final RegistrationRepository registrations;private final WaitlistRepository waitlists;private final EventRepository events;private final UserRepository users;private final TicketRepository tickets;@Value("${app.jwt.secret}") private String ticketSecret; private final NotificationService notifications; private final EmailService emailService; private final AuditLogService audit;private static final List<RegistrationStatus> ACTIVE=List.of(RegistrationStatus.REGISTERED,RegistrationStatus.ATTENDED);
@Transactional public RegistrationResponse register(String email,Long eventId){User user=currentUser(email);requireStudent(user);Event event=lockedEvent(eventId);validateOpen(event);Optional<Registration> existingRegistration=registrations.findByEventIdAndUserId(eventId,user.getId()); if(existingRegistration.isPresent() && existingRegistration.get().getStatus()!=RegistrationStatus.CANCELLED) throw new IllegalArgumentException("You are already registered or waitlisted for this event");if(waitlists.findByEventIdAndUserId(eventId,user.getId()).filter(w->w.getStatus()==WaitlistStatus.WAITING).isPresent())throw new IllegalArgumentException("You are already on the waitlist");if(registrations.countByEventIdAndStatusIn(eventId,ACTIVE)>=event.getMaxAttendees())throw new IllegalArgumentException("Event is full. Join the waitlist instead.");Registration r; if(existingRegistration.isPresent()){ r=existingRegistration.get(); if(r.getTicket()!=null){tickets.delete(r.getTicket());r.setTicket(null);} r.setRegistrationNumber(number("REG"));r.setRegisteredAt(Instant.now());r.setStatus(RegistrationStatus.REGISTERED); } else { r=Registration.builder().registrationNumber(number("REG")).event(event).user(user).status(RegistrationStatus.REGISTERED).build(); } r=registrations.save(r);createTicket(r);notifications.send(user,"Event Registration Successful","You have successfully registered for "+event.getTitle()+". Event date: "+event.getEventDate()+". Venue: "+event.getVenue().getName()+", "+event.getVenue().getCity()+". Registration status: REGISTERED.",NotificationType.EVENT_REGISTRATION);emailService.send(user.getEmail(),"EventHub registration confirmed","Registration "+r.getRegistrationNumber()+" confirmed for "+event.getTitle()+".");audit.log(user,"REGISTRATION","REGISTRATION",r.getId(),null,"Registration created");return RegistrationResponse.from(r);}
@Transactional public WaitlistResponse joinWaitlist(String email,Long eventId){User user=currentUser(email);requireStudent(user);Event event=lockedEvent(eventId);validateOpen(event);if(registrations.existsByEventIdAndUserIdAndStatusIn(eventId,user.getId(),List.of(RegistrationStatus.REGISTERED,RegistrationStatus.ATTENDED)))throw new IllegalArgumentException("You are already registered for this event");Optional<WaitlistEntry> existing=waitlists.findByEventIdAndUserId(eventId,user.getId());if(existing.isPresent()&&existing.get().getStatus()==WaitlistStatus.WAITING)throw new IllegalArgumentException("Already on waitlist");if(registrations.countByEventIdAndStatusIn(eventId,ACTIVE)<event.getMaxAttendees())throw new IllegalArgumentException("Seats are available. Register directly instead.");WaitlistEntry w=existing.orElseGet(()->WaitlistEntry.builder().event(event).user(user).build());w.setPosition(waitlists.maxPosition(eventId)+1);w.setStatus(WaitlistStatus.WAITING);w.setJoinedAt(Instant.now());w=waitlists.save(w);notifications.send(user,"Waitlist joined","You joined the waitlist for "+event.getTitle()+" at position "+w.getPosition()+".",NotificationType.WAITLIST);return WaitlistResponse.from(w);}
@Transactional public RegistrationResponse cancel(String email,Long eventId){User user=currentUser(email);Event event=lockedEvent(eventId);Registration r=registrations.findByEventIdAndUserId(eventId,user.getId()).orElseThrow(()->new IllegalArgumentException("Registration not found"));if(r.getStatus()!=RegistrationStatus.REGISTERED)throw new IllegalArgumentException("Only active registrations can be cancelled");if(event.getStatus()!=EventStatus.REGISTRATION_OPEN&&event.getStatus()!=EventStatus.REGISTRATION_CLOSED)throw new IllegalArgumentException("Registration can only be cancelled before the event starts");if(r.getTicket()!=null){tickets.delete(r.getTicket());r.setTicket(null);}r.setStatus(RegistrationStatus.CANCELLED);registrations.save(r);notifications.send(user,"Registration cancelled","Your registration for "+event.getTitle()+" was cancelled.",NotificationType.EVENT_UPDATE);emailService.send(user.getEmail(),"EventHub registration cancelled","Registration "+r.getRegistrationNumber()+" for "+event.getTitle()+" was cancelled.");audit.log(user,"REGISTRATION_CANCELLED","REGISTRATION",r.getId(),null,"Registration cancelled");promoteNext(event);return RegistrationResponse.from(r);}
@Transactional public WaitlistResponse cancelWaitlist(String email,Long eventId){User user=currentUser(email);lockedEvent(eventId);WaitlistEntry w=waitlists.findByEventIdAndUserId(eventId,user.getId()).orElseThrow(()->new IllegalArgumentException("Waitlist entry not found"));if(w.getStatus()!=WaitlistStatus.WAITING)throw new IllegalArgumentException("Waitlist entry is no longer active");w.setStatus(WaitlistStatus.CANCELLED);return WaitlistResponse.from(waitlists.save(w));}
@Transactional(readOnly=true) public Page<RegistrationResponse> mine(String email,int page,int size){User u=currentUser(email);return registrations.findByUserIdOrderByRegisteredAtDesc(u.getId(),PageRequest.of(Math.max(0,page),Math.min(Math.max(1,size),100))).map(RegistrationResponse::from);}
@Transactional(readOnly=true) public Page<WaitlistResponse> eventWaitlist(String email,Long eventId,int page,int size){Event e=events.findById(eventId).orElseThrow(()->new IllegalArgumentException("Event not found"));authorizeEventViewer(email,e);return waitlists.findByEventIdOrderByPositionAsc(eventId,PageRequest.of(Math.max(0,page),Math.min(Math.max(1,size),100))).map(WaitlistResponse::from);}
private void promoteNext(Event event){if(event.getStatus()!=EventStatus.REGISTRATION_OPEN)return;if(registrations.countByEventIdAndStatusIn(event.getId(),ACTIVE)>=event.getMaxAttendees())return;Optional<WaitlistEntry> next=waitlists.findFirstByEventIdAndStatusOrderByPositionAsc(event.getId(),WaitlistStatus.WAITING);if(next.isEmpty())return;WaitlistEntry w=next.get();Registration r=registrations.findByEventIdAndUserId(event.getId(),w.getUser().getId()).orElseGet(()->Registration.builder().event(event).user(w.getUser()).build());if(r.getTicket()!=null){tickets.delete(r.getTicket());r.setTicket(null);}r.setRegistrationNumber(number("REG"));r.setRegisteredAt(Instant.now());r.setStatus(RegistrationStatus.REGISTERED);r=registrations.save(r);createTicket(r);w.setStatus(WaitlistStatus.PROMOTED);waitlists.save(w);notifications.send(w.getUser(),"Waitlist promotion","A seat opened for "+event.getTitle()+" and you have been promoted.",NotificationType.WAITLIST);emailService.send(w.getUser().getEmail(),"EventHub waitlist promotion","You have been promoted from the waitlist for "+event.getTitle()+".");audit.log(w.getUser(),"WAITLIST_PROMOTION","REGISTRATION",r.getId(),null,"Waitlisted user promoted");}
private Ticket createTicket(Registration r){String id="TKT-"+UUID.randomUUID().toString().replace("-","").substring(0,16).toUpperCase();String signature=TicketSecurity.hmac(id,ticketSecret);Ticket t=tickets.save(Ticket.builder().ticketId(id).registration(r).secureTokenHash(signature).build());r.setTicket(t);return t;}
private void validateOpen(Event e){LocalDate today=LocalDate.now();if(e.getStatus()!=EventStatus.REGISTRATION_OPEN)throw new IllegalArgumentException("Registration is not open for this event");if(today.isBefore(e.getRegistrationStart())||today.isAfter(e.getRegistrationDeadline()))throw new IllegalArgumentException("Registration window is closed");}
private Event lockedEvent(Long id){return events.findByIdForUpdate(id).orElseThrow(()->new IllegalArgumentException("Event not found"));}private User currentUser(String email){return users.findByEmailIgnoreCase(email).orElseThrow(()->new IllegalArgumentException("User not found"));}private void requireStudent(User u){if(u.getRole()!=Role.STUDENT)throw new org.springframework.security.access.AccessDeniedException("Only students can register for events");}private void authorizeEventViewer(String email,Event e){User u=currentUser(email);if(u.getRole()==Role.ADMIN||u.getRole()==Role.SUPER_ADMIN)return;if(u.getRole()!=Role.ORGANIZER||!e.getOrganizer().getId().equals(u.getId()))throw new org.springframework.security.access.AccessDeniedException("Not authorized for this event");}private String number(String prefix){return prefix+"-"+UUID.randomUUID().toString().replace("-","").substring(0,18).toUpperCase();}}
